    "total" : 2, 
    "successful" : 2, 
    "failed" : 0 
  }, 
  "_seq_no" : 0, 
  "_primary_term" : 1 
}
```

#### 2.3 查询数据

由于数据分布在多个索引里，查询的时候要在符合条件的所有索引查询，可以使用下面的方法查询。

##### 2.3.1 使用逗号分割指定多个索引

```
GET /mylogs-2020061518-000001,mylogs-2020061519-000001/_search 
{"query":{"match_all":{}}}
```

##### 2.3.2 使用通配符查询

```
GET /mylogs-*/_search 
{ 
  "query": { 
    "match_all": {} 
  } 
}
```

执行结果：

```
{ 
  "took" : 0, 
  "timed_out" : false, 
  "_shards" : { 
    "total" : 1, 
    "successful" : 1, 
    "skipped" : 0, 
    "failed" : 0 
  }, 
  "hits" : { 
    "total" : { 
      "value" : 1, 
      "relation" : "eq" 
    }, 
    "max_score" : 1.0, 
    "hits" : [ 
      { 
        "_index" : "mylogs-2020061518-000001", 
        "_type" : "_doc", 
        "_id" : "VNZut3IBgpLCCHbxDzDB", 
